          "requestFeedback": true,
          "applicability": {
            "value": "",
            "mode": "query"
          },
          "condition": {
            "mode": "glide_scripted_query",
            "value": "(function execute(table) {\n\n    var gr = new GlideRecordSecure(table);\n\n    gr.addQuery('claim.claim_number', vaInputs.missing_doc_claim_number);\n\n    gr.setLimit(1);\n    gr.query();\n\n    if (gr.next()) {\n        return gr;\n    }\n\n    return null;\n\n})(table);"
          }
        },
